"""Tests for ansible.plugins.lookup.ini._parse_params (lines 96-119).

_parse_params is a pure helper: it only reads ``paramvals`` and builds its own
``defaultdict``, so no filesystem or global state is touched.  Each test still
verifies that the caller's mapping is left untouched to rule out state
pollution.
"""

from ansible.plugins.lookup.ini import _parse_params


def test_parse_params_multiple_keys_first_term_and_fresh_keys():
    """Covers: '=' in phrase (True), key match (True and False), the
    'idp == 0' branch, and the 'not params[thiskey]' branch for a brand-new
    key at idp > 0."""
    paramvals = {'section': '', 'key': '', 'value': ''}
    term = 'section=foo key=bar value=baz'

    result = _parse_params(term, paramvals)

    # each 'k=v' phrase starts a new entry, in order of first appearance
    assert result == ['section=foo', 'key=bar', 'value=baz']
    # helper must not mutate the caller's mapping
    assert paramvals == {'section': '', 'key': '', 'value': ''}


def test_parse_params_appends_to_existing_key():
    """Covers the else branch (line 116): a phrase without '=' is appended
    to the value of the current key, preserving the embedded space."""
    paramvals = {'key': ''}
    term = 'key=hello world'

    result = _parse_params(term, paramvals)

    assert result == ['key=hello world']
    assert paramvals == {'key': ''}


def test_parse_params_no_valid_key_match_keeps_default_key():
    """Covers '=' in phrase (True) but no valid key matching (inner 'if'
    False for every k): thiskey keeps its 'key' default."""
    paramvals = {'section': ''}
    term = 'unknown=foo'

    result = _parse_params(term, paramvals)

    # value lands under the default 'key' slot since no valid key matched
    assert result == ['unknown=foo']
    assert paramvals == {'section': ''}


def test_parse_params_leading_valueless_phrase_then_key():
    """First phrase has no '=' (line 105 False at idp == 0); the following
    'key=' phrase then finds params['key'] already set, so it is appended."""
    paramvals = {'key': ''}
    term = 'foo key=bar'

    result = _parse_params(term, paramvals)

    assert result == ['foo key=bar']
    assert paramvals == {'key': ''}


def test_parse_params_empty_term():
    """Empty term: the loop body never executes and an empty list is
    returned (covers the loop-exhausted path to line 119)."""
    paramvals = {'key': ''}

    result = _parse_params('', paramvals)

    assert result == []
    assert paramvals == {'key': ''}


def test_parse_params_repeated_key_appends():
    """The same key given twice: the second occurrence is appended to the
    first rather than starting a new entry."""
    paramvals = {'key': ''}
    term = 'key=a key=b'

    result = _parse_params(term, paramvals)

    assert result == ['key=a key=b']
    assert paramvals == {'key': ''}
